import {courseProgress,moduleProgress,learningMinutesBetween,projectProgress} from './metrics.js';
const today = new Date();
const dateKey = (d=today) => `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`;
const store = {read(k,f=[]){try{const value=JSON.parse(localStorage.getItem('northstar.'+k));return Array.isArray(value)?value:f}catch{return f}},write(k,v){localStorage.setItem('northstar.'+k,JSON.stringify(v))}};
let tasks=store.read('tasks'), habits=store.read('habits'), logs=store.read('habitLogs'), courses=store.read('courses'), modules=store.read('modules'), topics=store.read('topics'), sessions=store.read('learningSessions'), careerGoals=store.read('careerGoals'), projects=store.read('projects'), features=store.read('projectFeatures'), applications=store.read('applications'), events=store.read('events'), workouts=store.read('workouts'), measurements=store.read('bodyMeasurements'), books=store.read('books'), readingSessions=store.read('readingSessions'), knowledgeItems=store.read('knowledgeItems'), reflections=store.read('reflections'), accountEmail='',page='Dashboard';
const pages=['Dashboard','Calendar','Daily Planner','Habits','Career','Learning','Projects','Job Applications','Fitness','Reading','Knowledge Hub','Reports','Settings'];
const icons=['⌂','▦','▦','✓','↗','◉','◇','▤','⌁','▣','◌','▥','⚙'];
const nav=document.querySelector('#navigation');
nav.innerHTML=pages.map((p,i)=>`<button class="nav-link ${p===page?'active':''}" data-page="${p}"><span>${icons[i]}</span>${p}</button>`).join('');
const fmtDate=d=>new Intl.DateTimeFormat('en',{weekday:'long',month:'long',day:'numeric'}).format(d);
const escapeHtml=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function save(){const records={tasks,habits,habitLogs:logs,courses,modules,topics,learningSessions:sessions,careerGoals,projects,projectFeatures:features,applications,events,workouts,bodyMeasurements:measurements,books,readingSessions,knowledgeItems,reflections},previous=[];try{for(const k of Object.keys(records))previous.push([k,localStorage.getItem('northstar.'+k)]);for(const [k,v] of Object.entries(records))store.write(k,v);return true}catch(error){for(const [k,v] of previous){try{if(v===null)localStorage.removeItem('northstar.'+k);else localStorage.setItem('northstar.'+k,v)}catch{}}console.error('Could not persist Northstar data',error);toast('Save failed. Your changes are still on screen; check browser storage and retry.');return false}}
function todayTasks(){return tasks.filter(t=>t.date===dateKey()&&t.status!=='Cancelled')}
function weekStart(){const d=new Date(today);d.setHours(0,0,0,0);d.setDate(d.getDate()-((d.getDay()+6)%7));return d}
function weekDays(){const start=weekStart();return Array.from({length:7},(_,i)=>{const d=new Date(start);d.setDate(start.getDate()+i);return dateKey(d)})}
function completedHabit(h,date=dateKey()){return logs.find(l=>l.habitId===h.id&&l.date===date)?.status==='Completed'}
function render(){
 document.querySelector('#crumb').textContent=page; document.querySelectorAll('.nav-link[data-page]').forEach(b=>b.classList.toggle('active',b.dataset.page===page));
 const root=document.querySelector('#page');
 if(page==='Dashboard') root.innerHTML=dashboard();
 else if(page==='Daily Planner') root.innerHTML=planner();
 else if(page==='Habits') root.innerHTML=habitPage();
  else if(page==='Learning')root.innerHTML=learningPage();
  else if(page==='Career')root.innerHTML=careerPage();
  else if(page==='Projects')root.innerHTML=projectsPage();
  else if(page==='Job Applications')root.innerHTML=applicationsPage();
  else if(page==='Calendar')root.innerHTML=calendarPage();
  else if(page==='Fitness')root.innerHTML=fitnessPage();
  else if(page==='Reading')root.innerHTML=readingPage();
  else if(page==='Knowledge Hub')root.innerHTML=knowledgePage();
  else if(page==='Reports')root.innerHTML=reportsPage();
  else if(page==='Settings')root.innerHTML=settingsPage();
  else root.innerHTML=comingSoon(page);
  if(page==='Learning'){const filters=document.createElement('section');filters.className='panel learning-filters';filters.innerHTML=`<input class="search-input" id="learningSearch" placeholder="⌕ Search courses, topics or sessions"><select id="learningFilter"><option value="">All topic statuses</option>${['Not started','In progress','Needs revision','Completed'].map(x=>`<option>${x}</option>`).join('')}</select>`;root.querySelector('.stat-grid').after(filters)}
  if(page==='Job Applications'){const filters=root.querySelector('.applications-filters');if(filters&&!document.querySelector('#applicationSort')){const sort=document.createElement('select');sort.id='applicationSort';sort.setAttribute('aria-label','Sort applications');sort.innerHTML='<option value="date">Newest first</option><option value="company">Company name</option>';filters.append(sort);const sorted=[...applications].sort((a,b)=>(b.appliedDate||b.savedDate||'').localeCompare(a.appliedDate||a.savedDate||''));root.querySelectorAll('.application-row').forEach((row,i)=>row.dataset.sortdate=sorted[i]?.appliedDate||sorted[i]?.savedDate||'')}}
 bind();
}
function habitStreak(h){let count=0,d=new Date(today);while(completedHabit(h,dateKey(d))){count++;d.setDate(d.getDate()-1)}return count}
function dashboard(){
 const days=weekDays(),daySet=new Set(days),todays=todayTasks().sort((a,b)=>({High:0,Medium:1,Low:2}[a.priority]??3)-({High:0,Medium:1,Low:2}[b.priority]??3)),done=todays.filter(t=>t.status==='Completed').length,pct=todays.length?Math.round(done/todays.length*100):0;
 const activeHabits=habits.filter(h=>h.active!==false),habitDone=activeHabits.filter(h=>completedHabit(h)).length,habitPct=activeHabits.length?Math.round(habitDone/activeHabits.length*100):0;
 const mins=learningMinutesBetween(sessions,dateKey(),dateKey()),weekly=days.map(day=>learningMinutesBetween(sessions,day,day)),weekMinutes=weekly.reduce((a,b)=>a+b,0),max=Math.max(60,...weekly);
 const weekTasks=tasks.filter(t=>daySet.has(t.date)&&t.status!=='Cancelled'),weekDone=weekTasks.filter(t=>t.status==='Completed').length,weekTaskPct=weekTasks.length?Math.round(weekDone/weekTasks.length*100):0,weekHabits=logs.filter(l=>daySet.has(l.date)&&l.status==='Completed').length,weekSessions=sessions.filter(s=>daySet.has(s.date)).length;
 const todayEvents=events.filter(e=>e.date===dateKey()).sort((a,b)=>(a.startTime||'').localeCompare(b.startTime||'')),todayWorkouts=workouts.filter(w=>w.date===dateKey()).length,readingToday=readingSessions.filter(s=>s.date===dateKey()).reduce((n,s)=>n+(Number(s.pages)||0),0);
 const activeGoals=careerGoals.filter(g=>g.status!=='Completed'),activeProjects=projects.filter(p=>!['Completed','Archived'].includes(p.status)),activeCourses=courses.slice(0,3),upcoming=applications.flatMap(a=>[{kind:'Interview',date:a.interviewDate},{kind:'Follow-up',date:a.followUpDate}].filter(x=>x.date&&x.date>=dateKey()).map(x=>({...x,company:a.company}))).sort((a,b)=>a.date.localeCompare(b.date)).slice(0,2),appliedToday=applications.filter(a=>a.appliedDate===dateKey()).length;
 return `<section class="welcome"><div><span class="eyebrow">${fmtDate(new Date()).toUpperCase()}</span><h1>Make today <em>count.</em></h1><p>${todays.length?`${done} of ${todays.length} tasks complete. Keep your next priority in view.`:'A little progress, consistently, adds up to a lot.'}</p></div><button class="button primary" data-action="add-task"><span>＋</span> Plan a task</button></section>
 <section class="stat-grid"><article class="stat-card"><div class="stat-top"><span>Today's tasks</span><span class="stat-icon lavender">▦</span></div><div class="stat-number">${done}<span> / ${todays.length}</span></div><div class="progress-line"><i style="width:${pct}%"></i></div><small>${todays.length?`${pct}% completed`:'A clear day to begin'}</small></article><article class="stat-card"><div class="stat-top"><span>Focused learning</span><span class="stat-icon blue">◉</span></div><div class="stat-number">${(mins/60).toFixed(mins%60?1:0)}<span> hrs</span></div><small>${mins?'From recorded learning sessions':'Record a session to get started'}</small></article><article class="stat-card"><div class="stat-top"><span>Habits today</span><span class="stat-icon green">✓</span></div><div class="stat-number">${habitDone}<span> / ${activeHabits.length}</span></div><div class="progress-line"><i style="width:${habitPct}%"></i></div><small>${activeHabits.length?`${habitPct}% checked in`:'Create habits that matter'}</small></article><article class="stat-card"><div class="stat-top"><span>Applications today</span><span class="stat-icon amber">↗</span></div><div class="stat-number">${appliedToday}<span> submitted</span></div><small>${applications.length?`${applications.length} total tracked`:'No applications tracked yet'}</small></article></section>
 <section class="dashboard-grid"><article class="panel priorities"><div class="panel-heading"><div><span class="eyebrow">FOCUS</span><h2>Today's priorities</h2></div><button class="text-button" data-goto="Daily Planner">View planner <span>→</span></button></div>${todays.length?`<div class="task-list">${todays.slice(0,6).map(taskRow).join('')}</div>${todays.length>6?`<button class="text-button" data-goto="Daily Planner">View ${todays.length-6} more tasks →</button>`:''}`:`<div class="empty-inline"><div class="empty-mark">✳</div><b>Give the day a direction</b><span>Add a task to start shaping your day.</span><button class="text-button" data-action="add-task">＋ Add a task</button></div>`}</article>
 <article class="panel habit-widget"><div class="panel-heading"><div><span class="eyebrow">SHOW UP FOR YOURSELF</span><h2>Daily habits</h2></div><button class="icon-button" data-goto="Habits" aria-label="Manage habits">↗</button></div>${activeHabits.length?activeHabits.slice(0,4).map(habitRow).join(''):`<div class="empty-inline compact"><div class="empty-mark">✓</div><b>Consistency starts small</b><span>Add a habit and check in here each day.</span><button class="text-button" data-action="add-habit">＋ Create a habit</button></div>`}<div class="habit-summary"><b>${habitPct}%</b><span>of today's habits checked in</span><span class="streak-note">${activeHabits.filter(h=>habitStreak(h)>0).length?`${Math.max(...activeHabits.map(h=>habitStreak(h)))} day best current streak`: 'Start a new rhythm today'}</span></div></article>
 <article class="panel career-widget"><div class="panel-heading"><div><span class="eyebrow">DIRECTION & GROWTH</span><h2>Career goals</h2></div><button class="text-button" data-goto="Career">View goals →</button></div>${activeGoals.length?activeGoals.slice(0,3).map(g=>{const ms=g.milestones||[],p=ms.length?Math.round(ms.filter(m=>m.done).length/ms.length*100):0;return `<div class="goal-summary"><div class="metric-row"><b>${escapeHtml(g.title)}</b><span>${g.targetDate?`Target ${escapeHtml(g.targetDate)}`:escapeHtml(g.status)}</span></div><div class="progress-line"><i style="width:${p}%"></i></div></div>`}).join(''):`<div class="empty-inline compact"><b>Set a direction worth pursuing</b><span>Your goals and milestones will appear here.</span><button class="text-button" data-entity="goal">＋ Add a goal</button></div>`}</article>
 <article class="panel schedule-widget"><div class="panel-heading"><div><span class="eyebrow">PLAN YOUR TIME</span><h2>Today's schedule</h2></div><button class="text-button" data-goto="Calendar">Calendar →</button></div>${todayEvents.length?todayEvents.slice(0,5).map(e=>`<div class="event-summary"><time>${escapeHtml(e.startTime||'All day')}</time><div><b>${escapeHtml(e.title)}</b><small>${escapeHtml(e.category||'Event')}${e.location?' · '+escapeHtml(e.location):''}</small></div></div>`).join(''):`<div class="empty-inline compact"><div class="empty-mark">◷</div><b>Your calendar is clear</b><span>Add an event or appointment to plan your day.</span></div>`}<button class="button secondary full" data-entity="event">＋ Add an event</button></article>
 <article class="panel learning-widget"><div class="panel-heading"><div><span class="eyebrow">BUILDING MOMENTUM</span><h2>Learning progress</h2></div><button class="text-button" data-goto="Learning">Open learning →</button></div>${activeCourses.length?activeCourses.map(c=>{const p=courseProgress(c.id,modules,topics),ms=modules.filter(m=>m.courseId===c.id),count=topics.filter(t=>ms.some(m=>m.id===t.moduleId)).length,complete=topics.filter(t=>ms.some(m=>m.id===t.moduleId)&&t.status==='Completed').length;return `<div class="course-summary"><div class="metric-row"><b>${escapeHtml(c.title)}</b><span>${complete}/${count} topics</span></div><div class="progress-line"><i style="width:${p}%"></i></div></div>`}).join(''):`<div class="empty-inline compact"><b>Learning grows one topic at a time</b><span>Create a course to track topic progress and focused hours.</span><button class="text-button" data-entity="course">＋ Add a course</button></div>`}<div class="chart-caption">${(weekMinutes/60).toFixed(1)} focused hours this week · ${weekSessions} sessions</div></article>
 <article class="panel project-widget"><div class="panel-heading"><div><span class="eyebrow">MAKE THINGS REAL</span><h2>Project portfolio</h2></div><button class="text-button" data-goto="Projects">View projects →</button></div>${activeProjects.length?activeProjects.slice(0,3).map(p=>{const fs=features.filter(f=>f.projectId===p.id),pr=projectProgress(p.id,features),next=fs.find(f=>f.status!=='Completed');return `<div class="project-summary"><div class="metric-row"><b>${escapeHtml(p.name)}</b><span>${pr}% · ${escapeHtml(p.status||'Planned')}</span></div><div class="progress-line"><i style="width:${pr}%"></i></div><small>${next?`Next: ${escapeHtml(next.name)}`:'No pending features'}</small></div>`}).join(''):`<div class="empty-inline compact"><b>Your work, moving forward</b><span>Projects and feature progress show up here.</span><button class="text-button" data-entity="project">＋ Add a project</button></div>`}</article>
 <article class="panel consistency-widget"><div class="panel-heading"><div><span class="eyebrow">WEEKLY REVIEW</span><h2>Consistency summary</h2></div><button class="text-button" data-goto="Reports">Reports →</button></div><div class="consistency-metrics"><div><b>${weekDone}<span>/${weekTasks.length}</span></b><small>Tasks complete</small></div><div><b>${weekHabits}</b><small>Habit check-ins</small></div><div><b>${weekSessions}</b><small>Learning sessions</small></div></div><div class="metric-row"><span>Weekly task completion</span><b>${weekTaskPct}%</b></div><div class="progress-line"><i style="width:${weekTaskPct}%"></i></div><div class="chart-caption">${todayWorkouts} workout${todayWorkouts===1?'':'s'} today · ${readingToday} pages read today</div></article>
 <article class="panel quick-widget"><div class="panel-heading"><div><span class="eyebrow">KEEP MOVING</span><h2>Quick actions</h2></div></div><div class="quick-actions"><button class="quick-action" data-action="add-task"><span>＋</span>Add task</button><button class="quick-action" data-entity="session"><span>◉</span>Log learning</button><button class="quick-action" data-entity="project"><span>◇</span>Update project</button><button class="quick-action" data-entity="application"><span>↗</span>Add application</button><button class="quick-action" data-entity="workout"><span>⌁</span>Record workout</button><button class="quick-action" data-entity="reflection"><span>✧</span>Daily reflection</button></div><div class="upcoming-mini">${upcoming.length?upcoming.map(a=>`<div><span>${escapeHtml(a.company)} · ${a.kind}</span><b>${escapeHtml(a.date)}</b></div>`).join(''):'<small>No upcoming interview or follow-up dates.</small>'}</div></article></section><footer class="privacy-note"><span>◆</span> Your data stays in this browser on this device.</footer>`
}
function taskRow(t){return `<div class="task-row ${t.status==='Completed'?'is-done':''}"><button class="check-circle ${t.status==='Completed'?'checked':''}" data-task-toggle="${t.id}" aria-label="Toggle task">${t.status==='Completed'?'✓':''}</button><div class="task-copy"><b>${escapeHtml(t.title)}</b><small>${escapeHtml(t.category)}${t.status?` · ${escapeHtml(t.status)}`:''}${t.time?` · ${escapeHtml(t.time)}`:''}${t.duration?` · ${t.duration} min planned`:''}</small></div><span class="priority-dot ${(t.priority||'Medium').toLowerCase()}" title="${escapeHtml(t.priority||'Medium')} priority"></span><button class="row-more" data-edit-task="${t.id}" aria-label="Edit task">···</button></div>`}
function habitRow(h){return `<div class="habit-row"><div class="habit-symbol">${h.category==='Fitness'?'⌁':h.category==='Reading'?'▣':h.category==='Learning'?'◉':'✧'}</div><div class="habit-copy"><b>${escapeHtml(h.name)}</b><small>${escapeHtml(h.category)}</small></div><button class="habit-check ${completedHabit(h)?'checked':''}" data-habit-toggle="${h.id}" aria-label="Mark ${escapeHtml(h.name)} complete">${completedHabit(h)?'✓':'○'}</button></div>`}
function planner(){const list=[...tasks].sort((a,b)=>a.date.localeCompare(b.date));return `<section class="welcome"><div><span class="eyebrow">MAKE ROOM FOR WHAT MATTERS</span><h1>Daily planner</h1><p>Turn your intentions into a plan you can follow.</p></div><button class="button primary" data-action="add-task">＋ Add task</button></section><section class="panel planner-panel"><div class="panel-heading"><div><span class="eyebrow">${fmtDate(today).toUpperCase()}</span><h2>Your tasks <span class="count-pill">${todayTasks().length}</span></h2></div><input class="search-input" id="taskSearch" placeholder="⌕  Search tasks"></div><div class="filter-row"><select id="filterCategory"><option value="">All categories</option>${['Career','Learning','Project','Fitness','Reading','Personal','Other'].map(x=>`<option>${x}</option>`)}</select><select id="filterStatus"><option value="">All statuses</option>${['Not started','In progress','Completed','Postponed','Cancelled'].map(x=>`<option>${x}</option>`)}</select><select id="taskSort" aria-label="Sort tasks"><option value="date">Sort: date</option><option value="priority">Sort: priority</option><option value="title">Sort: title</option></select><span class="filter-spacer"></span><span class="summary">${todayTasks().filter(t=>t.status==='Completed').length} of ${todayTasks().length} done today</span></div><div class="planner-list" id="plannerList">${list.length?list.map(t=>`<div class="planner-task" data-category="${escapeHtml(t.category)}" data-status="${escapeHtml(t.status)}" data-title="${escapeHtml(t.title.toLowerCase())}" data-date="${escapeHtml(t.date)}" data-priority="${escapeHtml(t.priority||'Medium')}"><div class="task-date"><b>${t.date===dateKey()?'TODAY':new Intl.DateTimeFormat('en',{month:'short'}).format(new Date(t.date+'T12:00:00')).toUpperCase()}</b><span>${new Date(t.date+'T12:00:00').getDate()}</span></div>${taskRow(t)}<button class="postpone-task" data-postpone-task="${t.id}" aria-label="Postpone task to tomorrow" title="Move to tomorrow">↷</button><button class="delete-task" data-delete-task="${t.id}" aria-label="Delete task">×</button></div>`).join(''):`<div class="empty-inline"><div class="empty-mark">▦</div><b>Your plan starts here</b><span>Add a task to give your time a clear direction.</span><button class="button primary" data-action="add-task">＋ Add your first task</button></div>`}</div></section>`}
function habitPage(){const active=habits.filter(h=>h.active!==false);return `<section class="welcome"><div><span class="eyebrow">SMALL ACTIONS, REPEATED</span><h1>Build your <em>rhythm.</em></h1><p>Gentle consistency is more powerful than perfect streaks.</p></div><button class="button primary" data-action="add-habit">＋ New habit</button></section><section class="stat-grid habit-stats"><article class="stat-card"><div class="stat-top"><span>Today's check-ins</span><span class="stat-icon green">✓</span></div><div class="stat-number">${active.filter(h=>completedHabit(h)).length}<span> / ${active.length}</span></div><small>${active.length?'Every check-in counts':'Create your first habit'}</small></article><article class="stat-card"><div class="stat-top"><span>This week</span><span class="stat-icon lavender">◷</span></div><div class="stat-number">${weekDays().flatMap(d=>active.filter(h=>completedHabit(h,d))).length}<span> check-ins</span></div><small>Completed habit occurrences</small></article><article class="stat-card"><div class="stat-top"><span>Active habits</span><span class="stat-icon blue">✧</span></div><div class="stat-number">${active.length}<span> habits</span></div><small>Shape the routines you want</small></article><article class="stat-card"><div class="stat-top"><span>Approach</span><span class="stat-icon amber">♡</span></div><div class="stat-number" style="font-size:22px">Progress, not perfection</div><small>A missed day is simply a fresh start</small></article></section><section class="panel habit-page-panel"><div class="panel-heading"><div><span class="eyebrow">YOUR PRACTICE</span><h2>Today’s habits</h2></div><span class="summary">${fmtDate(today)}</span></div>${active.length?active.map(habitRow).join(''):`<div class="empty-inline"><div class="empty-mark">✓</div><b>Choose a habit worth repeating</b><span>Start with something small enough to do on an ordinary day.</span><button class="button primary" data-action="add-habit">＋ Create a habit</button></div>`}</section><section class="panel consistency-panel"><div class="panel-heading"><div><span class="eyebrow">LOOKING BACK</span><h2>Your consistency</h2></div><span class="chart-unit">LAST 7 DAYS</span></div><div class="consistency-grid">${weekDays().map((d,i)=>{const n=active.filter(h=>completedHabit(h,d)).length;const percent=active.length?n/active.length*100:0;return `<div class="consistency-day"><div class="consistency-cell ${percent?'has-progress':''}" style="--fill:${percent}%"><span>${percent?`${Math.round(percent)}%`:'—'}</span></div><small>${'MTWTFSS'[i]}</small></div>`}).join('')}</div><p class="chart-caption">A record of your check-ins. No streaks to break, just progress you can see.</p></section>`}
function learningPage(){const total=sessions.reduce((a,s)=>a+(Number(s.duration)||0),0),revision=topics.filter(t=>t.status==='Needs revision').length;return `<section class="welcome"><div><span class="eyebrow">LEARN WITH INTENTION</span><h1>Your <em>learning.</em></h1><p>Courses, topics, and focused sessions in one place.</p></div><div class="button-group"><button class="button secondary" data-entity="session">＋ Log session</button><button class="button primary" data-entity="course">＋ Add course</button></div></section><section class="stat-grid"><article class="stat-card"><div class="stat-top"><span>Focused hours</span><span class="stat-icon blue">◉</span></div><div class="stat-number">${(total/60).toFixed(total%60?1:0)}<span> hrs</span></div><small>From ${sessions.length} saved sessions</small></article><article class="stat-card"><div class="stat-top"><span>Courses</span><span class="stat-icon lavender">▣</span></div><div class="stat-number">${courses.length}<span> tracked</span></div><small>Course completion uses completed topics</small></article><article class="stat-card"><div class="stat-top"><span>Completed topics</span><span class="stat-icon green">✓</span></div><div class="stat-number">${topics.filter(t=>t.status==='Completed').length}<span> / ${topics.length}</span></div><small>${topics.length?'Based on defined topics':'Add topics to measure progress'}</small></article><article class="stat-card"><div class="stat-top"><span>Need revision</span><span class="stat-icon amber">↻</span></div><div class="stat-number">${revision}<span> topics</span></div><small>Self-assessed status</small></article></section><section class="learning-list">${courses.length?courses.map(courseCard).join(''):`<article class="panel empty-inline learning-empty"><div class="empty-mark">◉</div><b>Your learning plan starts here</b><span>Create a course, then organize it into modules and topics.</span><button class="button primary" data-entity="course">＋ Create a course</button></article>`}</section><section class="panel session-panel"><div class="panel-heading"><div><span class="eyebrow">FOCUSED PRACTICE</span><h2>Learning history</h2></div><button class="button secondary" data-entity="session">＋ Log session</button></div>${sessions.length?[...sessions].sort((a,b)=>b.date.localeCompare(a.date)).map(s=>`<div class="session-row"><div class="session-date"><b>${escapeHtml(s.date)}</b><small>${Number(s.duration)||0} min</small></div><div class="session-copy"><b>${escapeHtml(s.subject)}</b><small>${escapeHtml((courses.find(c=>c.id===s.courseId)?.title)||'Independent study')}${s.whatLearned?' · '+escapeHtml(s.whatLearned):''}</small></div><button class="row-more" data-entity="session" data-id="${s.id}" aria-label="Edit session">···</button><button class="delete-task" data-delete="session" data-id="${s.id}" aria-label="Delete session">×</button></div>`).join(''):`<div class="empty-inline compact"><b>No sessions recorded yet</b><span>Record focused time to show it on the dashboard.</span></div>`}</section>`}
function courseCard(c){const mods=modules.filter(m=>m.courseId===c.id), progress=courseProgress(c.id,modules,topics);return `<article class="panel course-card"><div class="course-head"><div><span class="eyebrow">${escapeHtml(c.institution||'COURSE')}</span><h2>${escapeHtml(c.title)}</h2><p>${escapeHtml(c.description||'')}</p></div><div class="course-actions"><button class="icon-button" data-entity="course" data-id="${c.id}" aria-label="Edit course">✎</button><button class="delete-task" data-delete="course" data-id="${c.id}" aria-label="Delete course">×</button></div></div><div class="metric-row"><span>Topic completion</span><b>${progress}%</b></div><div class="progress-line"><i style="width:${progress}%"></i></div><div class="module-list">${mods.length?mods.map(m=>{const ts=topics.filter(t=>t.moduleId===m.id),mp=moduleProgress(m.id,topics);return `<div class="module-block"><div class="module-head"><div><b>${escapeHtml(m.title)}</b><small>${mp}% · ${ts.filter(t=>t.status==='Completed').length}/${ts.length} topics complete</small></div><div><button class="text-button" data-entity="module" data-course="${c.id}" data-id="${m.id}">Edit</button><button class="text-button" data-delete="module" data-id="${m.id}">Delete</button><button class="text-button" data-entity="topic" data-module="${m.id}">＋ Topic</button></div></div>${ts.map(t=>`<div class="topic-row"><span class="topic-status ${t.status==='Completed'?'done':''}">${t.status==='Completed'?'✓':t.status==='Needs revision'?'↻':'○'}</span><div class="topic-copy"><b>${escapeHtml(t.title)}</b><small>${escapeHtml(t.status)}${t.confidence!==''&&t.confidence!=null?` · Confidence ${t.confidence}/5`:''}${t.score!==''&&t.score!=null?` · Score ${t.score}%`:''}${t.notes?' · '+escapeHtml(t.notes):''}</small></div><select class="topic-status-select" data-topic-status="${t.id}" aria-label="Change ${escapeHtml(t.title)} status">${['Not started','In progress','Needs revision','Completed'].map(x=>`<option ${x===t.status?'selected':''}>${x}</option>`).join('')}</select><button class="row-more" data-entity="topic" data-module="${m.id}" data-id="${t.id}" aria-label="Edit topic">···</button><button class="delete-task" data-delete="topic" data-id="${t.id}" aria-label="Delete topic">×</button></div>`).join('')||'<div class="no-topics">No topics yet.</div>'}</div>`}).join(''):'<div class="no-topics">Organize your course into modules.</div>'}</div><button class="button secondary" data-entity="module" data-course="${c.id}">＋ Add module</button></article>`}
function careerPage(){return `<section class="welcome"><div><span class="eyebrow">DIRECTION & GROWTH</span><h1>Career goals</h1><p>Keep the next milestone visible, then work toward it.</p></div><button class="button primary" data-entity="goal">＋ Add goal</button></section><section class="learning-list">${careerGoals.length?careerGoals.map(g=>{const milestones=g.milestones||[],progress=milestones.length?Math.round(milestones.filter(m=>m.done).length/milestones.length*100):g.status==='Completed'?100:0;return `<article class="panel goal-card"><div class="course-head"><div><span class="eyebrow">${escapeHtml(g.status||'IN PROGRESS')}${g.targetDate?' · TARGET '+escapeHtml(g.targetDate):''}</span><h2>${escapeHtml(g.title)}</h2><p>${escapeHtml(g.description||'')}</p></div><div class="course-actions"><button class="icon-button" data-entity="goal" data-id="${g.id}">✎</button><button class="delete-task" data-delete="goal" data-id="${g.id}">×</button></div></div><div class="metric-row"><span>Milestone completion</span><b>${progress}%</b></div><div class="progress-line"><i style="width:${progress}%"></i></div>${milestones.map((m,i)=>`<div class="habit-row"><button class="check-circle ${m.done?'checked':''}" aria-label="Mark ${escapeHtml(m.title)} ${m.done?'incomplete':'complete'}" data-goal-milestone="${g.id}:${i}">${m.done?'✓':''}</button><span class="task-copy"><b>${escapeHtml(m.title)}</b></span></div>`).join('')}<button class="text-button" data-entity="milestone" data-goal="${g.id}">＋ Add milestone</button></article>`}).join(''):'<div class="panel empty-inline learning-empty"><div class="empty-mark">↗</div><b>Choose a direction</b><span>Add a career goal and break it into milestones.</span><button class="button primary" data-entity="goal">＋ Create a goal</button></div>'}</section>`}
function projectsPage(){return `<section class="welcome"><div><span class="eyebrow">BUILD & REFLECT</span><h1>Project portfolio</h1><p>Track progress through features you actually complete.</p></div><button class="button primary" data-entity="project">＋ Add project</button></section><section class="learning-list">${projects.length?projects.map(p=>{const fs=features.filter(f=>f.projectId===p.id),prog=projectProgress(p.id,features);return `<article class="panel course-card"><div class="course-head"><div><span class="eyebrow">${escapeHtml(p.status||'PLANNED')}</span><h2>${escapeHtml(p.name)}</h2><p>${escapeHtml(p.description||'')}${p.github?` · <a href="${safeUrl(p.github)}" target="_blank" rel="noopener">GitHub</a>`:''}${p.deployment?` · <a href="${safeUrl(p.deployment)}" target="_blank" rel="noopener">Deployment</a>`:''}</p></div><div class="course-actions"><button class="icon-button" data-entity="project" data-id="${p.id}">✎</button><button class="delete-task" data-delete="project" data-id="${p.id}">×</button></div></div><div class="metric-row"><span>Completed features (${fs.filter(f=>f.status==='Completed').length}/${fs.length})</span><b>${prog}%</b></div><div class="progress-line"><i style="width:${prog}%"></i></div>${fs.map(f=>`<div class="topic-row"><span class="topic-copy"><b>${escapeHtml(f.name)}</b><small>${escapeHtml(f.status)}${f.notes?' · '+escapeHtml(f.notes):''}</small></span><select data-feature-status="${f.id}">${['Planned','In progress','Testing','Completed','Blocked'].map(x=>`<option ${x===f.status?'selected':''}>${x}</option>`).join('')}</select><button class="row-more" data-entity="feature" data-project="${p.id}" data-id="${f.id}">···</button></div>`).join('')}<button class="button secondary" data-entity="feature" data-project="${p.id}">＋ Add feature</button></article>`}).join(''):'<div class="panel empty-inline learning-empty"><div class="empty-mark">◇</div><b>Make your work visible</b><span>Add a project and track its features as they move forward.</span><button class="button primary" data-entity="project">＋ Create project</button></div>'}</section>`}
function applicationsPage(){const statuses=['Saved','Applied','Assessment','Interview','Offer','Rejected','Withdrawn'];return `<section class="welcome"><div><span class="eyebrow">A THOUGHTFUL JOB SEARCH</span><h1>Applications</h1><p>Track each opportunity and the next useful action.</p></div><button class="button primary" data-entity="application">＋ Add application</button></section><section class="stat-grid">${statuses.slice(0,4).map((s,i)=>`<article class="stat-card"><div class="stat-top"><span>${s}</span><span class="stat-icon ${['lavender','blue','amber','green'][i]}">↗</span></div><div class="stat-number">${applications.filter(a=>a.status===s).length}</div><small>Applications in this stage</small></article>`).join('')}</section><section class="panel applications-panel"><div class="applications-filters"><input class="search-input" id="applicationSearch" placeholder="⌕ Search company or title"><select id="applicationFilter"><option value="">All statuses</option>${statuses.map(x=>`<option>${x}</option>`).join('')}</select></div>${applications.length?[...applications].sort((a,b)=>(b.appliedDate||b.savedDate||'').localeCompare(a.appliedDate||a.savedDate||'')).map(a=>`<article class="application-row" data-status="${escapeHtml(a.status)}" data-search="${escapeHtml((a.company+' '+a.title).toLowerCase())}"><div class="application-main"><span class="eyebrow">${escapeHtml(a.status)}</span><h3>${escapeHtml(a.title)} · ${escapeHtml(a.company)}</h3><p>${escapeHtml(a.location||'')}${a.employmentType?' · '+escapeHtml(a.employmentType):''}${a.url?` · <a href="${safeUrl(a.url)}" target="_blank" rel="noopener">Job details</a>`:''}</p><small>${a.interviewDate?'Interview: '+escapeHtml(a.interviewDate)+' · ':''}${a.followUpDate?'Follow up: '+escapeHtml(a.followUpDate):''}${a.feedback?' · '+escapeHtml(a.feedback):''}</small></div><select data-application-status="${a.id}">${statuses.map(x=>`<option ${x===a.status?'selected':''}>${x}</option>`).join('')}</select><button class="icon-button" data-entity="application" data-id="${a.id}">✎</button><button class="delete-task" data-delete="application" data-id="${a.id}">×</button></article>`).join(''):'<div class="empty-inline"><div class="empty-mark">↗</div><b>Track opportunities with care</b><span>Applications and follow-up dates will stay together here.</span><button class="button primary" data-entity="application">＋ Add application</button></div>'}</section>`}
function calendarPage(){const list=[...events].sort((a,b)=>a.date.localeCompare(b.date)||(a.startTime||'').localeCompare(b.startTime||''));return `<section class="welcome"><div><span class="eyebrow">PLAN YOUR TIME</span><h1>Calendar</h1><p>Appointments, deadlines, and events alongside your plan.</p></div><button class="button primary" data-entity="event">＋ Add event</button></section><section class="panel calendar-panel"><div class="panel-heading"><div><span class="eyebrow">YOUR EVENTS</span><h2>Upcoming schedule</h2></div><input class="search-input" id="calendarDate" type="date" value=""></div>${list.length?list.map(e=>`<article class="event-row" data-date="${escapeHtml(e.date)}"><div class="event-date"><b>${escapeHtml(e.date)}</b><small>${escapeHtml(e.startTime||'All day')}${e.endTime?' – '+escapeHtml(e.endTime):''}</small></div><div class="event-copy"><b>${escapeHtml(e.title)}</b><small>${escapeHtml(e.category||'Event')}${e.location?' · '+escapeHtml(e.location):''}</small></div><button class="icon-button" data-entity="event" data-id="${e.id}">✎</button><button class="delete-task" data-delete="event" data-id="${e.id}">×</button></article>`).join(''):`<div class="empty-inline"><div class="empty-mark">◷</div><b>Your calendar is clear</b><span>Add appointments, deadlines, and events when they come up.</span><button class="button primary" data-entity="event">＋ Add your first event</button></div>`}</section>`}
function fitnessPage(){const total=workouts.reduce((n,w)=>n+(Number(w.duration)||0),0),latest=[...measurements].sort((a,b)=>b.date.localeCompare(a.date))[0];return `<section class="welcome"><div><span class="eyebrow">CARE FOR YOUR ENERGY</span><h1>Fitness</h1><p>Track activity and optional body measurements over time.</p></div><div class="button-group"><button class="button secondary" data-entity="measurement">＋ Measurement</button><button class="button primary" data-entity="workout">＋ Log workout</button></div></section><section class="stat-grid"><article class="stat-card"><div class="stat-top"><span>Workouts recorded</span><span class="stat-icon green">⌁</span></div><div class="stat-number">${workouts.length}</div><small>Across your saved history</small></article><article class="stat-card"><div class="stat-top"><span>Training time</span><span class="stat-icon blue">◷</span></div><div class="stat-number">${(total/60).toFixed(total%60?1:0)}<span> hrs</span></div><small>Sum of workout durations</small></article><article class="stat-card"><div class="stat-top"><span>Latest weight</span><span class="stat-icon lavender">↗</span></div><div class="stat-number">${latest?.weight?escapeHtml(latest.weight):'—'}<span>${latest?.weight?' kg':''}</span></div><small>${latest?`Recorded ${escapeHtml(latest.date)}`:'No measurement recorded'}</small></article><article class="stat-card"><div class="stat-top"><span>Today</span><span class="stat-icon amber">✓</span></div><div class="stat-number">${workouts.filter(w=>w.date===dateKey()).length}<span> workouts</span></div><small>Move at a pace that works for you</small></article></section><section class="panel module-panel"><div class="panel-heading"><div><span class="eyebrow">MOVEMENT HISTORY</span><h2>Workouts</h2></div></div>${workouts.length?[...workouts].sort((a,b)=>b.date.localeCompare(a.date)).map(w=>`<div class="session-row"><div class="session-date"><b>${escapeHtml(w.date)}</b><small>${Number(w.duration)||0} min</small></div><div class="session-copy"><b>${escapeHtml(w.type)}</b><small>${escapeHtml(w.notes||'Workout logged')}</small></div><button class="icon-button" data-entity="workout" data-id="${w.id}">✎</button><button class="delete-task" data-delete="workout" data-id="${w.id}">×</button></div>`).join(''):`<div class="empty-inline compact"><b>No workouts logged yet</b><span>Log activity to build a useful record over time.</span></div>`}</section><section class="panel module-panel"><div class="panel-heading"><div><span class="eyebrow">OPTIONAL PERSONAL RECORD</span><h2>Body measurements</h2></div></div>${measurements.length?[...measurements].sort((a,b)=>b.date.localeCompare(a.date)).map(m=>`<div class="session-row"><div class="session-date"><b>${escapeHtml(m.date)}</b></div><div class="session-copy"><b>${m.weight?`${escapeHtml(m.weight)} kg`:''}${m.bodyFat?` · ${escapeHtml(m.bodyFat)}% body fat`:''}</b><small>${escapeHtml(m.notes||'')}</small></div><button class="icon-button" data-entity="measurement" data-id="${m.id}">✎</button><button class="delete-task" data-delete="measurement" data-id="${m.id}">×</button></div>`).join(''):`<div class="empty-inline compact"><b>No measurements saved</b><span>Measurements are optional.</span></div>`}</section>`}
function readingPage(){const pagesRead=readingSessions.reduce((n,s)=>n+(Number(s.pages)||0),0);return `<section class="welcome"><div><span class="eyebrow">MAKE TIME TO READ</span><h1>Reading</h1><p>Track books and reading sessions at your own pace.</p></div><div class="button-group"><button class="button secondary" data-entity="readingSession">＋ Log session</button><button class="button primary" data-entity="book">＋ Add book</button></div></section><section class="stat-grid"><article class="stat-card"><div class="stat-top"><span>Reading</span><span class="stat-icon blue">▣</span></div><div class="stat-number">${books.filter(b=>b.status!=='Completed').length}<span> books</span></div><small>Planned or in progress</small></article><article class="stat-card"><div class="stat-top"><span>Pages logged</span><span class="stat-icon green">↗</span></div><div class="stat-number">${pagesRead}</div><small>${readingSessions.length} saved sessions</small></article><article class="stat-card"><div class="stat-top"><span>Books finished</span><span class="stat-icon lavender">✓</span></div><div class="stat-number">${books.filter(b=>b.status==='Completed').length}</div><small>Based on book status</small></article><article class="stat-card"><div class="stat-top"><span>Reading time</span><span class="stat-icon amber">◷</span></div><div class="stat-number">${(readingSessions.reduce((n,s)=>n+(Number(s.minutes)||0),0)/60).toFixed(1)}<span> hrs</span></div><small>Recorded session minutes</small></article></section><section class="reading-list">${books.length?books.map(b=>{const percent=Number(b.totalPages)?Math.min(100,Math.round((Number(b.currentPage)||0)/Number(b.totalPages)*100)):b.status==='Completed'?100:0;return `<article class="panel book-card"><div class="course-head"><div><span class="eyebrow">${escapeHtml(b.status||'Not started')}</span><h2>${escapeHtml(b.title)}</h2><p>${escapeHtml(b.author||'')}</p></div><div class="course-actions"><button class="icon-button" data-entity="book" data-id="${b.id}">✎</button><button class="delete-task" data-delete="book" data-id="${b.id}">×</button></div></div><div class="metric-row"><span>${b.currentPage||0}${b.totalPages?` / ${b.totalPages} pages`:' pages read'}</span><b>${percent}%</b></div><div class="progress-line"><i style="width:${percent}%"></i></div><button class="text-button" data-entity="readingSession" data-book="${b.id}">＋ Log reading session</button></article>`}).join(''):`<div class="panel empty-inline learning-empty"><div class="empty-mark">▣</div><b>Your next good read starts here</b><span>Add a book and log sessions to track pages and time.</span><button class="button primary" data-entity="book">＋ Add a book</button></div>`}</section><section class="panel session-panel"><div class="panel-heading"><div><span class="eyebrow">READING HISTORY</span><h2>Recent sessions</h2></div></div>${readingSessions.length?[...readingSessions].sort((a,b)=>b.date.localeCompare(a.date)).map(s=>`<div class="session-row"><div class="session-date"><b>${escapeHtml(s.date)}</b><small>${Number(s.minutes)||0} min · ${Number(s.pages)||0} pages</small></div><div class="session-copy"><b>${escapeHtml(books.find(b=>b.id===s.bookId)?.title||'Reading')}</b><small>${escapeHtml(s.notes||'')}</small></div><button class="icon-button" data-entity="readingSession" data-id="${s.id}">✎</button><button class="delete-task" data-delete="readingSession" data-id="${s.id}">×</button></div>`).join(''):`<div class="empty-inline compact"><b>No reading sessions yet</b><span>Log pages or minutes when you finish a session.</span></div>`}</section>`}
function knowledgePage(){const categories=['Technology','AI','Business','Finance','Current affairs','Career','Other'];return `<section class="welcome"><div><span class="eyebrow">SAVE WHAT YOU WANT TO REMEMBER</span><h1>Knowledge hub</h1><p>A searchable library of useful links and your notes.</p></div><button class="button primary" data-entity="knowledge">＋ Save an item</button></section><section class="panel applications-panel"><div class="applications-filters"><input class="search-input" id="knowledgeSearch" placeholder="⌕ Search saved items"><select id="knowledgeCategory"><option value="">All categories</option>${categories.map(c=>`<option>${c}</option>`).join('')}</select></div>${knowledgeItems.length?knowledgeItems.map(k=>`<article class="knowledge-row" data-search="${escapeHtml((k.title+' '+(k.notes||'')+' '+(k.tags||'')).toLowerCase())}" data-category="${escapeHtml(k.category||'Other')}"><div class="application-main"><span class="eyebrow">${escapeHtml(k.category||'Other')}</span><h3>${k.url?`<a href="${safeUrl(k.url)}" target="_blank" rel="noopener">${escapeHtml(k.title)}</a>`:escapeHtml(k.title)}</h3><p>${escapeHtml(k.notes||'')}${k.tags?' · '+escapeHtml(k.tags):''}</p></div><button class="icon-button" data-entity="knowledge" data-id="${k.id}">✎</button><button class="delete-task" data-delete="knowledge" data-id="${k.id}">×</button></article>`).join(''):`<div class="empty-inline"><div class="empty-mark">◌</div><b>Keep useful knowledge close</b><span>Save an article, link, and the reason you want to revisit it.</span><button class="button primary" data-entity="knowledge">＋ Save your first item</button></div>`}</section>`}
function reportBounds(type){const end=new Date();end.setHours(0,0,0,0);if(type==='month')return [dateKey(new Date(end.getFullYear(),end.getMonth(),1)),dateKey(end)];const start=weekStart(),sunday=new Date(start);sunday.setDate(start.getDate()+6);return [dateKey(start),dateKey(sunday)]}
function reportData(type){const [start,end]=reportBounds(type),within=d=>d>=start&&d<=end,planned=tasks.filter(t=>within(t.date)&&t.status!=='Cancelled'),completed=planned.filter(t=>t.status==='Completed').length,read=readingSessions.filter(s=>within(s.date)),focus=learningMinutesBetween(sessions,start,end);return {start,end,planned:planned.length,completed,rate:planned.length?Math.round(completed/planned.length*100):0,focus,learningSessions:sessions.filter(s=>within(s.date)).length,habitLogs:logs.filter(l=>within(l.date)&&l.status==='Completed').length,applications:applications.filter(a=>a.appliedDate&&within(a.appliedDate)).length,workouts:workouts.filter(w=>within(w.date)).length,readingPages:read.reduce((n,s)=>n+(Number(s.pages)||0),0),readingSessions:read.length,topics:topics.filter(t=>t.status==='Completed').length,reflections:reflections.filter(r=>within(r.date)).length}}
function reportsPage(){const type=document.querySelector('#reportPeriod')?.value||'week',r=reportData(type),label=type==='week'?'This week':'This month';return `<section class="welcome"><div><span class="eyebrow">MEASURE WHAT YOU DID</span><h1>Reports</h1><p>Measured activity and your reflections, kept distinct.</p></div><div class="button-group"><select id="reportPeriod" aria-label="Report period"><option value="week" ${type==='week'?'selected':''}>This week</option><option value="month" ${type==='month'?'selected':''}>This month</option></select><button class="button secondary" data-export-report>Export CSV</button><button class="button secondary" data-print-report>Print</button></div></section><section class="panel report-range"><span class="eyebrow">${label.toUpperCase()} · ${escapeHtml(r.start)} – ${escapeHtml(r.end)}</span></section><section class="stat-grid report-stats"><article class="stat-card"><div class="stat-top"><span>Tasks</span><span class="stat-icon lavender">▦</span></div><div class="stat-number">${r.completed}<span> / ${r.planned}</span></div><small>${r.rate}% of non-cancelled planned tasks completed</small></article><article class="stat-card"><div class="stat-top"><span>Focused learning</span><span class="stat-icon blue">◉</span></div><div class="stat-number">${(r.focus/60).toFixed(1)}<span> hrs</span></div><small>${r.learningSessions} saved sessions</small></article><article class="stat-card"><div class="stat-top"><span>Habit check-ins</span><span class="stat-icon green">✓</span></div><div class="stat-number">${r.habitLogs}</div><small>Completed occurrences</small></article><article class="stat-card"><div class="stat-top"><span>Applications</span><span class="stat-icon amber">↗</span></div><div class="stat-number">${r.applications}</div><small>Submitted in this period</small></article><article class="stat-card"><div class="stat-top"><span>Workouts</span><span class="stat-icon green">⌁</span></div><div class="stat-number">${r.workouts}</div><small>Saved workouts</small></article><article class="stat-card"><div class="stat-top"><span>Reading</span><span class="stat-icon blue">▣</span></div><div class="stat-number">${r.readingPages}<span> pages</span></div><small>${r.readingSessions} sessions</small></article><article class="stat-card"><div class="stat-top"><span>Completed topics</span><span class="stat-icon lavender">✓</span></div><div class="stat-number">${r.topics}</div><small>Current completed topics, not period-scoped</small></article><article class="stat-card"><div class="stat-top"><span>Reflections</span><span class="stat-icon amber">✧</span></div><div class="stat-number">${r.reflections}</div><small>User-entered notes in this period</small></article></section><section class="panel reflection-panel"><div class="panel-heading"><div><span class="eyebrow">YOUR OWN WORDS</span><h2>Reflections</h2></div><button class="button primary" data-entity="reflection">＋ Add reflection</button></div>${reflections.length?[...reflections].sort((a,b)=>b.date.localeCompare(a.date)).map(x=>`<div class="reflection-row"><div><b>${escapeHtml(x.date)} · ${escapeHtml(x.kind||'Daily')}</b><p>${escapeHtml(x.wins||'')}${x.obstacles?' · Obstacles: '+escapeHtml(x.obstacles):''}${x.nextSteps?' · Next: '+escapeHtml(x.nextSteps):''}</p></div><button class="icon-button" data-entity="reflection" data-id="${x.id}">✎</button><button class="delete-task" data-delete="reflection" data-id="${x.id}">×</button></div>`).join(''):`<div class="empty-inline compact"><b>Make space to reflect</b><span>These notes are separate from measured activity.</span></div>`}</section>`}
function exportReport(){const type=document.querySelector('#reportPeriod')?.value||'week',r=reportData(type),rows=[['Metric','Value','Definition'],['Range',`${r.start} to ${r.end}`,'Local calendar dates'],['Tasks planned',r.planned,'Excludes cancelled tasks'],['Tasks completed',r.completed,'Completed planned tasks'],['Task completion rate',`${r.rate}%`,'Completed divided by planned tasks'],['Learning minutes',r.focus,'Sum of session durations'],['Learning sessions',r.learningSessions,'Saved sessions in range'],['Habit check-ins',r.habitLogs,'Completed dated habit logs'],['Applications submitted',r.applications,'Applied date falls in range'],['Workouts',r.workouts,'Saved workouts in range'],['Pages read',r.readingPages,'Sum of reading session pages'],['Reading sessions',r.readingSessions,'Saved reading sessions'],['Completed topics',r.topics,'Current total, not date-scoped'],['Reflections',r.reflections,'User-entered reflections in range']],csv=rows.map(row=>row.map(v=>`"${String(v).replaceAll('"','""')}"`).join(',')).join('\r\n'),blob=new Blob([csv],{type:'text/csv;charset=utf-8'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=`northstar-${type}-${r.start}.csv`;a.click();URL.revokeObjectURL(url);toast('Report exported')}
function exportBackup(){const backup={application:'Northstar',version:1,exportedAt:new Date().toISOString(),data:{tasks,habits,habitLogs:logs,courses,modules,topics,learningSessions:sessions,careerGoals,projects,projectFeatures:features,applications,events,workouts,bodyMeasurements:measurements,books,readingSessions,knowledgeItems,reflections}},blob=new Blob([JSON.stringify(backup,null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=`northstar-backup-${dateKey()}.json`;a.click();URL.revokeObjectURL(url);toast('Backup downloaded')}
async function importBackup(file){try{const backup=JSON.parse(await file.text());if(backup.application!=='Northstar'||!backup.data||typeof backup.data!=='object')throw new Error('This is not a Northstar backup.');if(!confirm('Merge these records into this browser? Existing IDs will be kept and duplicate IDs skipped.'))return;const before=allState(),pairs=[['tasks','tasks'],['habits','habits'],['habitLogs','logs'],['courses','courses'],['modules','modules'],['topics','topics'],['learningSessions','sessions'],['careerGoals','careerGoals'],['projects','projects'],['projectFeatures','features'],['applications','applications'],['events','events'],['workouts','workouts'],['bodyMeasurements','measurements'],['books','books'],['readingSessions','readingSessions'],['knowledgeItems','knowledgeItems'],['reflections','reflections']];for(const [key] of pairs)if(backup.data[key]!==undefined&&!Array.isArray(backup.data[key]))throw new Error(`Invalid ${key} list in backup.`);for(const [key,stateKey] of pairs){const incoming=backup.data[key];if(Array.isArray(incoming)){const current=({tasks,habits,logs,courses,modules,topics,sessions,careerGoals,projects,features,applications,events,workouts,measurements,books,readingSessions,knowledgeItems,reflections})[stateKey],ids=new Set(current.map(x=>x.id));current.push(...incoming.filter(x=>x&&typeof x==='object'&&typeof x.id==='string'&&!ids.has(x.id)))}}if(!save()){restore(before);return}render();toast('Backup merged')}catch(error){console.error('Northstar backup import failed',error);toast(error.message||'Could not read that backup file')}}
function settingsPage(){const counts={tasks:tasks.length,habits:habits.length,courses:courses.length,projects:projects.length,applications:applications.length,events:events.length,workouts:workouts.length,books:books.length,knowledgeItems:knowledgeItems.length};return `<section class="welcome"><div><span class="eyebrow">YOUR WORKSPACE</span><h1>Settings</h1><p>Manage your theme and keep a portable copy of your records.</p></div></section><section class="panel settings-card"><div class="panel-heading"><div><span class="eyebrow">APPEARANCE</span><h2>Midnight Emerald</h2></div><button class="theme-toggle" data-toggle-theme>◐ Toggle theme</button></div><p>Your theme preference is saved in this browser.</p></section><section class="panel settings-card"><div class="panel-heading"><div><span class="eyebrow">CLOUD SYNC</span><h2>${accountEmail?'MongoDB account connected':'Connect an account'}</h2></div><span class="status-pill">${accountEmail?'SYNC READY':'OPTIONAL'}</span></div>${accountEmail?`<p>Signed in as ${escapeHtml(accountEmail)}. Sync merges records by ID and keeps a local copy.</p><div class="button-group"><button class="button primary" data-sync-now>Sync this device</button><button class="button secondary" data-cloud-logout>Sign out</button></div>`:`<p>Create an account or sign in to sync this browser’s records to your MongoDB database. Your current local data stays in place.</p><form id="cloudAuthForm"><div class="form-grid"><label>Email<input name="email" type="email" required maxlength="254" autocomplete="email"></label><label>Password<input name="password" type="password" required minlength="12" maxlength="128" autocomplete="current-password"><small>At least 12 characters.</small></label></div><div class="button-group"><button class="button primary" type="submit" data-auth-mode="login">Sign in</button><button class="button secondary" type="submit" data-auth-mode="register">Create account</button></div></form>`}<small class="settings-help" id="cloudStatus">${accountEmail?'':'Sync is optional; records remain available offline in this browser.'}</small></section><section class="panel settings-card"><div class="panel-heading"><div><span class="eyebrow">DATA & PRIVACY</span><h2>Local browser storage</h2></div><span class="status-pill">PRIVATE TO THIS BROWSER</span></div><p>Your browser remains a local copy. Export a backup before changing browsers or connecting a remote database.</p><div class="data-counts">${Object.entries(counts).map(([label,count])=>`<span>${escapeHtml(label.replaceAll('Items',' items'))}<b>${count}</b></span>`).join('')}</div><div class="button-group"><button class="button primary" data-export-backup>Download data backup</button><label class="button secondary import-label">Merge backup<input type="file" id="importBackup" accept="application/json" hidden></label></div><small class="settings-help">Import merges by record ID and keeps existing records when IDs match.</small></section>`}
function safeUrl(url){try{const u=new URL(url);return ['http:','https:'].includes(u.protocol)?escapeHtml(u.href):'#'}catch{return '#'}}
function comingSoon(name){return `<section class="welcome"><div><span class="eyebrow">NORTHSTAR WORKSPACE</span><h1>${escapeHtml(name)}</h1><p>Your personal growth workspace, built one useful step at a time.</p></div></section><section class="panel roadmap-card"><div class="roadmap-mark">✳</div><span class="eyebrow">COMING IN A LATER PHASE</span><h2>${escapeHtml(name)} is on the roadmap.</h2><p>The first release focuses on a working daily planner, habit check-ins, and a dashboard backed by your saved data. This area will be added as the app grows.</p><button class="button secondary" data-goto="Dashboard">Back to dashboard <span>→</span></button></section>`}
function bindLegacy(){document.querySelectorAll('[data-page]').forEach(b=>b.onclick=()=>{page=b.dataset.page;document.querySelector('#sidebar').classList.remove('open');render()});document.querySelectorAll('[data-goto]').forEach(b=>b.onclick=()=>{page=b.dataset.goto;render()});document.querySelectorAll('[data-action="add-task"]').forEach(b=>b.onclick=()=>openTask());document.querySelectorAll('[data-action="add-habit"]').forEach(b=>b.onclick=()=>document.querySelector('#habitDialog').showModal());document.querySelectorAll('[data-task-toggle]').forEach(b=>b.onclick=()=>{const t=tasks.find(x=>x.id===b.dataset.taskToggle);t.status=t.status==='Completed'?'Not started':'Completed';if(t.status==='Completed')t.actual=t.actual||t.duration;save();render()});document.querySelectorAll('[data-habit-toggle]').forEach(b=>b.onclick=()=>toggleHabit(b.dataset.habitToggle));document.querySelectorAll('[data-edit-task]').forEach(b=>b.onclick=()=>openTask(tasks.find(t=>t.id===b.dataset.editTask)));document.querySelectorAll('[data-postpone-task]').forEach(b=>b.onclick=()=>{const t=tasks.find(x=>x.id===b.dataset.postponeTask);const d=new Date(t.date+'T12:00:00');d.setDate(d.getDate()+1);t.date=dateKey(d);t.status='Postponed';save();render();toast('Task moved to tomorrow')});document.querySelectorAll('[data-delete-task]').forEach(b=>b.onclick=()=>{tasks=tasks.filter(t=>t.id!==b.dataset.deleteTask);save();render();toast('Task deleted')});const search=document.querySelector('#taskSearch');if(search)search.oninput=filterTasks;['filterCategory','filterStatus'].forEach(id=>{const el=document.querySelector('#'+id);if(el)el.onchange=filterTasks})}
function bind(){document.querySelectorAll('[data-page]').forEach(b=>b.onclick=()=>{page=b.dataset.page;document.querySelector('#sidebar').classList.remove('open');render()});document.querySelectorAll('[data-goto]').forEach(b=>b.onclick=()=>{page=b.dataset.goto;render()});document.querySelectorAll('[data-action="add-task"]').forEach(b=>b.onclick=()=>openTask());document.querySelectorAll('[data-action="add-habit"]').forEach(b=>b.onclick=()=>document.querySelector('#habitDialog').showModal());document.querySelectorAll('[data-task-toggle]').forEach(b=>b.onclick=()=>{const before=allState(),t=tasks.find(x=>x.id===b.dataset.taskToggle);t.status=t.status==='Completed'?'Not started':'Completed';if(t.status==='Completed')t.actual=t.actual||t.duration;if(save())render();else restore(before)});document.querySelectorAll('[data-habit-toggle]').forEach(b=>b.onclick=()=>toggleHabit(b.dataset.habitToggle));document.querySelectorAll('[data-edit-task]').forEach(b=>b.onclick=()=>openTask(tasks.find(t=>t.id===b.dataset.editTask)));document.querySelectorAll('[data-postpone-task]').forEach(b=>b.onclick=()=>{const before=allState(),t=tasks.find(x=>x.id===b.dataset.postponeTask),d=new Date(t.date+'T12:00:00');d.setDate(d.getDate()+1);t.date=dateKey(d);t.status='Postponed';if(save()){render();toast('Task moved to tomorrow')}else restore(before)});document.querySelectorAll('[data-delete-task]').forEach(b=>b.onclick=()=>{if(!confirm('Delete this task?'))return;const before=allState();tasks=tasks.filter(t=>t.id!==b.dataset.deleteTask);if(save()){render();toast('Task deleted')}else restore(before)});const search=document.querySelector('#taskSearch');if(search)search.oninput=filterTasks;['filterCategory','filterStatus'].forEach(id=>{const el=document.querySelector('#'+id);if(el)el.onchange=filterTasks});const taskSort=document.querySelector('#taskSort');if(taskSort)taskSort.onchange=sortTaskRows;const appSearch=document.querySelector('#applicationSearch');if(appSearch)appSearch.oninput=filterApplications;const appFilter=document.querySelector('#applicationFilter');if(appFilter)appFilter.onchange=filterApplications;const appSort=document.querySelector('#applicationSort');if(appSort)appSort.onchange=sortApplicationRows}
function sortTaskRows(){const list=document.querySelector('#plannerList'),mode=document.querySelector('#taskSort')?.value||'date';if(!list)return;const rank={High:0,Medium:1,Low:2};[...list.querySelectorAll('.planner-task')].sort((a,b)=>mode==='priority'?(rank[a.dataset.priority]??3)-(rank[b.dataset.priority]??3)||a.dataset.date.localeCompare(b.dataset.date):mode==='title'?a.dataset.title.localeCompare(b.dataset.title):a.dataset.date.localeCompare(b.dataset.date)).forEach(el=>list.append(el))}
function sortApplicationRows(){const panel=document.querySelector('.applications-panel'),mode=document.querySelector('#applicationSort')?.value||'date';if(!panel)return;[...panel.querySelectorAll('.application-row')].sort((a,b)=>mode==='company'?a.querySelector('h3').textContent.localeCompare(b.querySelector('h3').textContent):b.dataset.sortdate.localeCompare(a.dataset.sortdate)).forEach(el=>panel.append(el))}
function filterTasks(){const q=(document.querySelector('#taskSearch').value||'').toLowerCase(),cat=document.querySelector('#filterCategory').value,status=document.querySelector('#filterStatus').value;document.querySelectorAll('.planner-task').forEach(el=>el.hidden=!(el.dataset.title.includes(q)&&(!cat||el.dataset.category===cat)&&(!status||el.dataset.status===status)))}
function openTask(task){const d=document.querySelector('#taskDialog'),f=document.querySelector('#taskForm');f.reset();f.elements.id.value=task?.id||'';f.elements.title.value=task?.title||'';f.elements.category.value=task?.category||'Learning';f.elements.priority.value=task?.priority||'Medium';f.elements.date.value=task?.date||dateKey();f.elements.time.value=task?.time||'';f.elements.duration.value=task?.duration||'';f.elements.actual.value=task?.actual||'';f.elements.notes.value=task?.notes||'';document.querySelector('#dialogTitle').textContent=task?'Edit task':'Add a task';d.showModal()}
function toggleHabit(id){const before=allState(),exists=logs.find(l=>l.habitId===id&&l.date===dateKey());if(exists)logs=logs.filter(l=>l!==exists);else logs.push({id:crypto.randomUUID(),habitId:id,date:dateKey(),status:'Completed'});if(!save()){restore(before);return}render()}
