const table={course:()=>courses,module:()=>modules,topic:()=>topics,session:()=>sessions,goal:()=>careerGoals,project:()=>projects,feature:()=>features,application:()=>applications,milestone:()=>[],event:()=>events,workout:()=>workouts,measurement:()=>measurements,book:()=>books,readingSession:()=>readingSessions,knowledge:()=>knowledgeItems,reflection:()=>reflections};
