function cloudCollections(){return {tasks,habits,habitLogs:logs,courses,modules,topics,learningSessions:sessions,careerGoals,projects,projectFeatures:features,applications,events,workouts,bodyMeasurements:measurements,books,readingSessions,knowledgeItems,reflections}}
async function cloudRequest(url,options={}){const response=await fetch(url,{...options,credentials:'same-origin',headers:{'Content-Type':'application/json',...(options.headers||{})}});const result=await response.json().catch(()=>({}));if(!response.ok)throw new Error(result.error||'Could not reach the sync service.');return result}
async function syncWorkspace(){const collections=cloudCollections(),response=await cloudRequest('/api/sync'),incoming=response.data||{},before=allState();for(const [key,current] of Object.entries(collections)){const remote=incoming[key];if(!Array.isArray(remote))continue;const ids=new Set(current.map(x=>x.id));current.push(...remote.filter(x=>x&&typeof x.id==='string'&&!ids.has(x.id)))}if(!save()){restore(before);throw new Error('Could not save merged records to this browser.')}await cloudRequest('/api/sync',{method:'POST',body:JSON.stringify({data:cloudCollections()})});render();toast('Workspace synced with MongoDB')}
async function checkCloudSession(){try{const account=await cloudRequest('/api/auth/session');accountEmail=account.email;render()}catch{accountEmail=''}}
document.querySelector('#page').addEventListener('submit',async e=>{if(e.target.id!=='cloudAuthForm')return;e.preventDefault();const submit=e.submitter,mode=submit?.dataset.authMode,form=new FormData(e.target),status=document.querySelector('#cloudStatus');submit.disabled=true;if(status)status.textContent=mode==='register'?'Creating account…':'Signing in…';try{const account=await cloudRequest('/api/auth/'+mode,{method:'POST',body:JSON.stringify({email:form.get('email'),password:form.get('password')})});accountEmail=account.email;await syncWorkspace()}catch(error){if(status)status.textContent=error.message;else toast(error.message)}finally{if(submit.isConnected)submit.disabled=false}});
document.querySelector('#page').addEventListener('click',async e=>{const b=e.target.closest('[data-sync-now],[data-cloud-logout]');if(!b)return;b.disabled=true;try{if(b.hasAttribute('data-sync-now'))await syncWorkspace();else{await cloudRequest('/api/auth/logout',{method:'POST'});accountEmail='';render();toast('Signed out')}}catch(error){toast(error.message)}finally{if(b.isConnected)b.disabled=false}});
