Object.assign(specs,{event:[['title','Event title','text',1],['date','Date','date',1],['startTime','Start time','time'],['endTime','End time','time'],['category','Type','select',['Appointment','Deadline','Personal','Work','Other']],['location','Location','text'],['notes','Notes','textarea']],workout:[['type','Workout','select',['Strength','Cardio','Walking','Running','Cycling','Yoga','Sports','Other']],['date','Date','date',1],['duration','Duration (minutes)','number',1],['notes','Notes','textarea']],measurement:[['date','Date','date',1],['weight','Weight (kg)','number'],['bodyFat','Body fat (%)','number'],['notes','Notes','textarea']],book:[['title','Book title','text',1],['author','Author','text'],['status','Status','select',['Not started','In progress','Completed']],['totalPages','Total pages','number'],['currentPage','Current page','number'],['startDate','Start date','date'],['finishDate','Finish date','date'],['notes','Notes','textarea']],readingSession:[['bookId','Book','book'],['date','Date','date',1],['pages','Pages read','number'],['minutes','Duration (minutes)','number'],['notes','Notes','textarea']],knowledge:[['title','Title','text',1],['url','URL','url'],['category','Category','select',['Technology','AI','Business','Finance','Current affairs','Career','Other']],['tags','Tags','text'],['notes','Notes','textarea']],reflection:[['date','Date','date',1],['kind','Reflection type','select',['Daily','Weekly']],['wins','What went well?','textarea'],['obstacles','What got in the way?','textarea'],['nextSteps','What will you focus on next?','textarea']]});
function openEntity(type,id='',parent=''){const rows=table[type]();const current=rows.find(x=>x.id===id)||{};const form=document.querySelector('#entityForm');form.dataset.type=type;form.dataset.id=id;form.dataset.parent=parent;document.querySelector('#entityEyebrow').textContent=type.toUpperCase();document.querySelector('#entityTitle').textContent=`${id?'Edit':'Add'} ${type==='session'?'learning session':type==='readingSession'?'reading session':type}`;const fields=specs[type]||[];document.querySelector('#entityFields').innerHTML=fields.map(([key,label,kind,opts])=>{let input='';const value=current[key]??(key==='date'?dateKey():key==='status'?(type==='topic'?'Not started':type==='application'?'Saved':type==='project'?'Planned':type==='book'?'Not started':'In progress'):'');if(kind==='textarea')input=`<textarea name="${key}" rows="2" ${opts===1?'required':''}>${escapeHtml(value)}</textarea>`;else if(kind==='select')input=`<select name="${key}" ${opts===1?'required':''}>${opts.map(o=>`<option ${value===o?'selected':''}>${o}</option>`).join('')}</select>`;else if(kind==='course')input=`<select name="${key}"><option value="">Independent</option>${courses.map(c=>`<option value="${c.id}" ${value===c.id?'selected':''}>${escapeHtml(c.title)}</option>`).join('')}</select>`;else if(kind==='book')input=`<select name="${key}"><option value="">Select a book</option>${books.map(b=>`<option value="${b.id}" ${value===b.id||parent===b.id?'selected':''}>${escapeHtml(b.title)}</option>`).join('')}</select>`;else if(kind==='topic'){const courseId=current.courseId||document.querySelector('#entityFields [name=courseId]')?.value;input=`<select name="${key}"><option value="">—</option>${topics.filter(t=>!courseId||modules.find(m=>m.id===t.moduleId)?.courseId===courseId).map(t=>`<option value="${t.id}" ${value===t.id?'selected':''}>${escapeHtml(t.title)}</option>`).join('')}</select>`}else input=`<input type="${kind}" name="${key}" value="${escapeHtml(value)}" ${opts===1?'required':''} ${kind==='number'?`min="0" max="${key==='confidence'?5:key==='score'?100:key==='bodyFat'?100:key==='weight'?500:1440}" step="1"`:''}>`;return `<label class="entity-field">${label}${input}</label>`}).join('');document.querySelector('#entityDialog').showModal()}
function removeRecord(type,id){const before=allState();if(type==='course'){const children=modules.filter(m=>m.courseId===id).map(m=>m.id),topicIds=topics.filter(t=>children.includes(t.moduleId)).map(t=>t.id);if(!confirm('Delete this course and all its modules, topics, and linked learning sessions?'))return;modules=modules.filter(m=>m.courseId!==id);topics=topics.filter(t=>!topicIds.includes(t.id));sessions=sessions.filter(s=>s.courseId!==id&&!topicIds.includes(s.topicId));courses=courses.filter(x=>x.id!==id)}else if(type==='module'){const topicIds=topics.filter(t=>t.moduleId===id).map(t=>t.id);if(!confirm('Delete this module and its topics and linked sessions?'))return;modules=modules.filter(x=>x.id!==id);topics=topics.filter(x=>x.moduleId!==id);sessions=sessions.filter(x=>!topicIds.includes(x.topicId))}else if(type==='project'){if(!confirm('Delete this project and its features?'))return;projects=projects.filter(x=>x.id!==id);features=features.filter(x=>x.projectId!==id)}else if(type==='book'){if(!confirm('Delete this book and its reading sessions?'))return;books=books.filter(x=>x.id!==id);readingSessions=readingSessions.filter(x=>x.bookId!==id)}else{const labels={topic:'Delete this topic and linked learning sessions?',session:'Delete this learning session?',goal:'Delete this career goal and its milestones?',feature:'Delete this feature?',application:'Delete this application?',event:'Delete this calendar event?',workout:'Delete this workout?',measurement:'Delete this measurement?',readingSession:'Delete this reading session?',knowledge:'Delete this saved item?',reflection:'Delete this reflection?'};if(!confirm(labels[type]||'Delete this record?'))return;if(type==='topic'){topics=topics.filter(x=>x.id!==id);sessions=sessions.filter(x=>x.topicId!==id)}if(type==='session')sessions=sessions.filter(x=>x.id!==id);if(type==='goal')careerGoals=careerGoals.filter(x=>x.id!==id);if(type==='feature')features=features.filter(x=>x.id!==id);if(type==='application')applications=applications.filter(x=>x.id!==id);if(type==='event')events=events.filter(x=>x.id!==id);if(type==='workout')workouts=workouts.filter(x=>x.id!==id);if(type==='measurement')measurements=measurements.filter(x=>x.id!==id);if(type==='readingSession'){const item=readingSessions.find(x=>x.id===id),book=books.find(x=>x.id===item?.bookId);if(book)book.currentPage=Math.max(0,(Number(book.currentPage)||0)-(Number(item.pages)||0));readingSessions=readingSessions.filter(x=>x.id!==id)}if(type==='knowledge')knowledgeItems=knowledgeItems.filter(x=>x.id!==id);if(type==='reflection')reflections=reflections.filter(x=>x.id!==id)}if(!save()){restore(before);return}render();toast('Record deleted')}
document.querySelector('#entityForm').addEventListener('submit',e=>{e.preventDefault();const form=e.currentTarget,type=form.dataset.type,id=form.dataset.id,parent=form.dataset.parent,fd=new FormData(form),before=allState(),values=Object.fromEntries(fd.entries()),rows=table[type](),existing=rows.find(x=>x.id===id),record={...(existing||{}),...values,id:id||crypto.randomUUID()};for(const k of ['confidence','score','duration','weight','bodyFat','totalPages','currentPage','pages','minutes'])if(k in values)record[k]=values[k]===''?'':Number(values[k]);if(type==='module')record.courseId=parent;if(type==='topic')record.moduleId=parent;if(type==='feature')record.projectId=parent;if(type==='readingSession'&&parent&&!record.bookId)record.bookId=parent;if(type==='reflection'&&!record.date)record.date=dateKey();if(type==='milestone'){const goal=careerGoals.find(g=>g.id===parent);goal.milestones=[...(goal.milestones||[]),{title:record.title,done:false}]}else if(existing){const i=rows.findIndex(x=>x.id===id);rows[i]=record}else rows.push(record);if(type==='readingSession'){const book=books.find(b=>b.id===record.bookId),oldPages=Number(existing?.pages)||0;if(book)book.currentPage=Math.max(0,(Number(book.currentPage)||0)+(Number(record.pages)||0)-oldPages)}if(!save()){restore(before);return}document.querySelector('#entityDialog').close();render();toast(id?'Changes saved':'Record added')});
document.querySelector('#cancelEntity').onclick=()=>document.querySelector('#entityDialog').close();
document.querySelector('#entityFields').addEventListener('change',e=>{if(e.target.name==='courseId'){const topic=document.querySelector('#entityFields [name=topicId]');if(topic){const courseId=e.target.value;topic.innerHTML='<option value="">—</option>'+topics.filter(t=>!courseId||modules.find(m=>m.id===t.moduleId)?.courseId===courseId).map(t=>`<option value="${t.id}">${escapeHtml(t.title)}</option>`).join('')}}});
document.querySelector('#entityFields').addEventListener('input',e=>{if(e.target.name==='confidence'||e.target.name==='score'){e.target.setCustomValidity(e.target.value===''?'':Number(e.target.value)<0||Number(e.target.value)>(e.target.name==='confidence'?5:100)?`Enter a value from 0 to ${e.target.name==='confidence'?5:100}`:'')}});
window.addEventListener('storage',e=>{if(e.key==='northstar.theme'||e.key==='northstar.dark'){const dark=e.key==='northstar.theme'?e.newValue!=='light':e.newValue!=='0';document.documentElement.classList.toggle('dark',dark);document.documentElement.classList.toggle('light',!dark);document.querySelector('#themeToggle').title=dark?'Switch to light theme':'Switch to Midnight Emerald theme';return}const value=e.newValue===null?[]:(()=>{try{const parsed=JSON.parse(e.newValue);return Array.isArray(parsed)?parsed:null}catch{return null}})();if(!value)return;switch(e.key?.replace('northstar.','')){case'tasks':tasks=value;break;case'habits':habits=value;break;case'habitLogs':logs=value;break;case'courses':courses=value;break;case'modules':modules=value;break;case'topics':topics=value;break;case'learningSessions':sessions=value;break;case'careerGoals':careerGoals=value;break;case'projects':projects=value;break;case'projectFeatures':features=value;break;case'applications':applications=value;break;case'events':events=value;break;case'workouts':workouts=value;break;case'bodyMeasurements':measurements=value;break;case'books':books=value;break;case'readingSessions':readingSessions=value;break;case'knowledgeItems':knowledgeItems=value;break;case'reflections':reflections=value;break;default:return}render()});
document.querySelector('#page').addEventListener('click',e=>{const button=e.target.closest('[data-entity],[data-delete],[data-goal-milestone],[data-export-report],[data-print-report],[data-export-backup],[data-toggle-theme]');if(!button)return;if(button.dataset.entity){e.preventDefault();openEntity(button.dataset.entity,button.dataset.id||'',button.dataset.course||button.dataset.module||button.dataset.project||button.dataset.goal||button.dataset.book||'')}if(button.dataset.delete){e.preventDefault();removeRecord(button.dataset.delete,button.dataset.id)}if(button.hasAttribute('data-export-report')){e.preventDefault();exportReport()}if(button.hasAttribute('data-print-report')){e.preventDefault();window.print()}if(button.hasAttribute('data-export-backup')){e.preventDefault();exportBackup()}if(button.hasAttribute('data-toggle-theme')){e.preventDefault();document.querySelector('#themeToggle').click()}if(button.dataset.goalMilestone){const [goalId,index]=button.dataset.goalMilestone.split(':');const g=careerGoals.find(x=>x.id===goalId),before=allState();g.milestones[index].done=!g.milestones[index].done;if(save())render();else restore(before)}});
document.querySelector('#page').addEventListener('input',e=>{if(e.target.id==='applicationSearch')filterApplications();if(e.target.id==='learningSearch')filterLearning();if(e.target.id==='knowledgeSearch')filterKnowledge();if(e.target.id==='calendarDate')filterCalendar()});
document.querySelector('#page').addEventListener('change',e=>{if(e.target.id==='applicationFilter'){filterApplications();return}if(e.target.id==='learningFilter'){filterLearning();return}if(e.target.id==='knowledgeCategory'){filterKnowledge();return}if(e.target.id==='reportPeriod'){render();return}if(e.target.id==='calendarDate'){filterCalendar();return}if(e.target.id==='importBackup'&&e.target.files?.[0]){importBackup(e.target.files[0]);return}const topicId=e.target.dataset.topicStatus,featureId=e.target.dataset.featureStatus,appId=e.target.dataset.applicationStatus;if(!topicId&&!featureId&&!appId)return;const before=allState();if(topicId)topics.find(t=>t.id===topicId).status=e.target.value;if(featureId)features.find(t=>t.id===featureId).status=e.target.value;if(appId)applications.find(t=>t.id===appId).status=e.target.value;if(save())render();else restore(before)});
function filterApplications(){const q=(document.querySelector('#applicationSearch')?.value||'').toLowerCase(),status=document.querySelector('#applicationFilter')?.value||'';document.querySelectorAll('.application-row').forEach(row=>row.hidden=!(row.dataset.search.includes(q)&&(!status||row.dataset.status===status)))}
function filterLearning(){const q=(document.querySelector('#learningSearch')?.value||'').toLowerCase(),status=document.querySelector('#learningFilter')?.value||'';document.querySelectorAll('.course-card').forEach(card=>{const head=card.querySelector('.course-head')?.textContent.toLowerCase()||'',rows=[...card.querySelectorAll('.topic-row')];rows.forEach(row=>{const statusSelect=row.querySelector('[data-topic-status]'),matchesStatus=!status||statusSelect?.value===status,matchesText=!q||head.includes(q)||row.textContent.toLowerCase().includes(q);row.hidden=!(matchesStatus&&matchesText)});const matchesHead=!q||head.includes(q),matchesTopic=rows.some(r=>!r.hidden);card.hidden=!(matchesHead||matchesTopic)});document.querySelectorAll('.session-row').forEach(row=>row.hidden=!!q&&!row.textContent.toLowerCase().includes(q))}
function filterKnowledge(){const q=(document.querySelector('#knowledgeSearch')?.value||'').toLowerCase(),category=document.querySelector('#knowledgeCategory')?.value||'';document.querySelectorAll('.knowledge-row').forEach(row=>row.hidden=!(row.dataset.search.includes(q)&&(!category||row.dataset.category===category)))}
function filterCalendar(){const date=document.querySelector('#calendarDate')?.value||'';document.querySelectorAll('.event-row').forEach(row=>row.hidden=!!date&&row.dataset.date!==date)}
document.querySelector('#taskForm').addEventListener('submit',e=>{e.preventDefault();const before=allState(),f=e.currentTarget,d=new FormData(f),id=d.get('id');const existing=tasks.find(t=>t.id===id);const item={...(existing||{}),id:id||crypto.randomUUID(),title:d.get('title').trim(),category:d.get('category'),priority:d.get('priority'),date:d.get('date'),time:d.get('time'),duration:d.get('duration'),actual:d.get('actual'),notes:d.get('notes'),status:existing?.status||'Not started'};if(existing)tasks=tasks.map(t=>t.id===id?item:t);else tasks.push(item);if(!save()){restore(before);return}document.querySelector('#taskDialog').close();render();toast(existing?'Task updated':'Task added')});
document.querySelector('#habitForm').addEventListener('submit',e=>{e.preventDefault();const before=allState(),d=new FormData(e.currentTarget);habits.push({id:crypto.randomUUID(),name:d.get('name').trim(),category:d.get('category'),active:true,created:dateKey()});if(!save()){restore(before);return}e.currentTarget.closest('dialog').close();render();toast('Habit created')});
document.querySelector('#cancelDialog').onclick=()=>document.querySelector('#taskDialog').close();document.querySelector('#cancelHabit').onclick=()=>document.querySelector('#habitDialog').close();
const preferredTheme=(()=>{try{return localStorage.getItem('northstar.theme')||(localStorage.getItem('northstar.dark')==='0'?'light':'dark')}catch{return'dark'}})();document.documentElement.classList.toggle('dark',preferredTheme!=='light');document.documentElement.classList.toggle('light',preferredTheme==='light');document.querySelector('#themeToggle').title=preferredTheme==='light'?'Switch to Midnight Emerald theme':'Switch to light theme';document.querySelector('#themeToggle').setAttribute('aria-label',document.querySelector('#themeToggle').title);document.querySelector('#themeToggle').onclick=()=>{const dark=!document.documentElement.classList.contains('dark');document.documentElement.classList.toggle('dark',dark);document.documentElement.classList.toggle('light',!dark);const next=dark?'dark':'light';document.querySelector('#themeToggle').title=dark?'Switch to light theme':'Switch to Midnight Emerald theme';document.querySelector('#themeToggle').setAttribute('aria-label',document.querySelector('#themeToggle').title);try{localStorage.setItem('northstar.theme',next)}catch{toast('Theme changed for this page, but could not be saved')}};
document.querySelector('#menuToggle').onclick=()=>document.querySelector('#sidebar').classList.toggle('open');render();
